/**
 * Resolves a path alias to its entity coordinates.
 *
 * The language is always required — there is no fallback across languages.
 * This keeps the system deterministic and the URL self-describing
 * (the caller always knows which language they will get back).
 *
 * Storage layout (generated by Drupal's AliasBucketManager):
 *   <aliasDir>/<langcode>/<pidBucket>/<sanitizedAlias>/data.json
 *
 *   data.json contents:
 *     { "entityType": "node", "entityId": "1" }
 */

import { readFile, readdir } from 'node:fs/promises';
import { join } from 'node:path';
import { sanitizeAliasPath } from './path-utils.js';

/**
 * Resolves a path alias to its entity coordinates.
 *
 * @param {string} aliasDir
 *   Path to the alias-buckets root directory.
 * @param {string} alias
 *   The raw alias (e.g., "about-us" or "/about-us").
 * @param {string} lang
 *   Language code that scopes the lookup. Required — pass the validated
 *   code from the route handler.
 *
 * @returns {Promise<{entityType: string, entityId: string, langcode: string}|null>}
 *   The resolved entity coordinates and langcode, or null if not found.
 */
export async function resolveAlias(aliasDir, alias, lang) {
  const safe = sanitizeAliasPath(alias);
  return resolveInLanguage(aliasDir, lang, safe);
}

/**
 * Searches for the alias in a single language directory.
 *
 * Iterates bucket directories under <aliasDir>/<langcode>/ looking for
 * a `data.json` that maps to the sanitized alias.
 *
 * @returns {Promise<{entityType: string, entityId: string, langcode: string}|null>}
 */
async function resolveInLanguage(aliasDir, langcode, safeAlias) {
  const langDir = join(aliasDir, langcode);
  let buckets;
  try {
    buckets = await readdir(langDir);
  }
  catch {
    return null;
  }

  for (const bucket of buckets) {
    const candidate = join(langDir, bucket, safeAlias, 'data.json');
    const mapping = await readMapping(candidate);
    if (mapping) {
      return { ...mapping, langcode };
    }
  }

  return null;
}

/**
 * Reads and validates a data.json mapping file.
 *
 * @returns {Promise<{entityType: string, entityId: string}|null>}
 *   Null if the file is missing, unreadable, or has the wrong shape.
 */
async function readMapping(filePath) {
  try {
    const content = await readFile(filePath, 'utf-8');
    const data = JSON.parse(content);
    if (typeof data?.entityType === 'string' && typeof data?.entityId === 'string') {
      return { entityType: data.entityType, entityId: data.entityId };
    }
  }
  catch {
    return null;
  }
  return null;
}
